WITH parsed AS (SELECT id, effective_from, tier_prices, discounts, ELEMENT_AT(tier_prices, 1) AS entry_price, ARRAY_MIN(tier_prices) AS lowest_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT DATE_TRUNC('MONTH', effective_from) AS activity_month, CASE WHEN avg_tier_price >= 29 THEN 'LARGE' ELSE 'SMALL' END AS avg_tier_price_tier, DATE_TRUNC('WEEK', effective_from) AS week_start, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(avg_tier_price, ARRAY(0.25, 0.5, 0.75)) AS avg_tier_price_quartiles, GROUPING_ID() AS grouping_level FROM parsed GROUP BY ROLLUP (DATE_TRUNC('MONTH', effective_from), CASE WHEN avg_tier_price >= 29 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('WEEK', effective_from)) ORDER BY avg_tier_price_tier DESC
